{
  "technical_and_design_decisions": [
    "Admin UI Job Creation (U1): Investigate REST API security filter chain and role mapping vs Shell execution paths; surface nested server-side exceptions properly to logs and HTTP response payload.",
    "Explicit Partitioning (U2): Extend Stream Deployment options and Binder SPI to accept explicit partition count overrides per producer module.",
    "Dynamic Kafka Subscriptions (U3): Upgrade Kafka binder/source consumer handling to support pattern matching and dynamic partition rebalance listeners.",
    "HDFS Sink Enhancements (U4 & U5): Introduce boolean properties `useSyncable` and `useInUseSuffix` (defaulting to true) in `HdfsTextWrittenOption` and `HdfsDataWriter` pipeline to manage flush/sync behavior and stream output paths.",
    "Module Automation Plugins (U6): Create Maven mojo and Gradle task leveraging the Spring XD Admin REST API `/modules` endpoint for artifact deployment.",
    "Custom Module Versioning (U7): Extend module registry coordinates to include version identifiers (`type/name/version`) and update stream parser resolution to support versioned artifacts.",
    "PHD 3.0 Certification (U8): Upgrade Hadoop dependencies to match Pivotal HD 3.0 / ODP baseline and verify binary compatibility across HDFS, YARN, and MapReduce integration tests."
  ],
  "assumptions": [
    "Development work is carried out by a single experienced senior Java developer familiar with the Spring Framework, Spring XD architecture, Kafka, and Hadoop ecosystems.",
    "A local/virtual PHD 3.0 and Kafka test environment is available or easy to stand up for integration verification.",
    "Existing REST APIs for module upload require minimal backend modification to support Maven/Gradle artifact pushing.",
    "Effort estimates include developer testing (unit and integration tests), code documentation, and bug fixing during development."
  ],
  "activities": [
    {
      "activity_id": "ACT-1",
      "activity_name": "Fix Admin UI Job Creation Role Issue and Logging (U1)",
      "activity_description": "Investigate REST/UI authorization discrepancy for ROLE_CREATE and ROLE_ADMIN during job creation, fix UI security controller mapping, and add detailed exception logging in the admin server.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-2",
      "activity_name": "Implement Explicit Partition Count Configuration (U2)",
      "activity_description": "Add support for explicit partition count properties in module deployment manifests, message bus binders, and routing logic.",
      "most_likely_effort": 3.0
    },
    {
      "activity_id": "ACT-3",
      "activity_name": "Add Dynamic Partition Subscription to Kafka Source Module (U3)",
      "activity_description": "Enhance Kafka source module to support dynamic partition assignment and subscription patterns without needing fixed partition mappings.",
      "most_likely_effort": 3.5
    },
    {
      "activity_id": "ACT-4",
      "activity_name": "Implement Syncable Writes Option for HDFS Sink (U4)",
      "activity_description": "Extend HDFS sink module options to allow enabling Syncable HDFS API writes for immediate flush and improved resiliency on sink failure.",
      "most_likely_effort": 2.5
    },
    {
      "activity_id": "ACT-5",
      "activity_name": "Add Option to Disable inUseSuffix in HDFS Sink (U5)",
      "activity_description": "Modify HDFS file writer logic to support direct writing to final output filenames without applying temporary file extensions like .tmp.",
      "most_likely_effort": 2.0
    },
    {
      "activity_id": "ACT-6",
      "activity_name": "Develop Maven and Gradle Plugin Targets for Custom Module Upload (U6)",
      "activity_description": "Implement build tool plugin goals/tasks to automate packaging and uploading custom module fragments directly to the Spring XD registry via REST endpoints.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-7",
      "activity_name": "Implement Custom Module Versioning Support (U7)",
      "activity_description": "Extend module registry, stream deployment engine, and module resolution mechanisms to support module semantic versioning and incremental rollouts.",
      "most_likely_effort": 5.0
    },
    {
      "activity_id": "ACT-8",
      "activity_name": "Certify Spring XD against PHD 3.0 (U8)",
      "activity_description": "Update Hadoop dependency matrices to Pivotal HD 3.0 / ODP standards, execute integration test suites against PHD 3.0, and resolve compatibility issues.",
      "most_likely_effort": 4.0
    },
    {
      "activity_id": "ACT-9",
      "activity_name": "End-to-End Integration Testing & Documentation",
      "activity_description": "Perform full system integration testing across all updated modules, verify build artifacts, and update user/developer documentation.",
      "most_likely_effort": 3.5
    }
  ],
  "reported_total": {
    "most_likely_effort": 30.0
  }
}
